INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'B', 35, $${"kind": "listening", "part": "B", "partTitle": "Part B — Long Conversations", "script": [{"s": "W", "t": "Did you see the listing for the apartment on Maple Street?"}, {"s": "M", "t": "Yeah, but it's way out of my budget. I'm looking for something under six hundred a month."}, {"s": "W", "t": "My cousin is moving out of her place next month. It's a two-bedroom, and the rent is pretty reasonable."}, {"s": "M", "t": "How far is it from campus?"}, {"s": "W", "t": "About a fifteen-minute walk. And there's a bus stop right outside."}, {"s": "M", "t": "That sounds perfect. When can I take a look at it?"}, {"s": "W", "t": "She's free this Saturday afternoon. I could go with you if you want."}, {"s": "M", "t": "That would be great. Thanks for thinking of me."}], "id": "LIS-B-02-Q2", "scriptId": "LIS-B-02", "stem": "What is the man's budget?", "options": ["Under $600 a month.", "Around $800 a month.", "Exactly $600 a month.", "He has no fixed budget."], "answer": 0, "explanation": "Pria itu berkata I'm looking for something under six hundred a month, jadi anggarannya di bawah 600 dolar per bulan. Pilihan B dan C angkanya tidak tepat. Pilihan D salah karena ia menyebut batas anggarannya."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'B', 36, $${"kind": "listening", "part": "B", "partTitle": "Part B — Long Conversations", "script": [{"s": "W", "t": "Did you see the listing for the apartment on Maple Street?"}, {"s": "M", "t": "Yeah, but it's way out of my budget. I'm looking for something under six hundred a month."}, {"s": "W", "t": "My cousin is moving out of her place next month. It's a two-bedroom, and the rent is pretty reasonable."}, {"s": "M", "t": "How far is it from campus?"}, {"s": "W", "t": "About a fifteen-minute walk. And there's a bus stop right outside."}, {"s": "M", "t": "That sounds perfect. When can I take a look at it?"}, {"s": "W", "t": "She's free this Saturday afternoon. I could go with you if you want."}, {"s": "M", "t": "That would be great. Thanks for thinking of me."}], "id": "LIS-B-02-Q3", "scriptId": "LIS-B-02", "stem": "What can be inferred about the cousin's apartment?", "options": ["It is far from campus.", "It is already rented.", "It is too expensive.", "It meets the man's needs."], "answer": 3, "explanation": "Apartemen itu sewanya wajar (reasonable), hanya lima belas menit jalan kaki dari kampus, dan ada halte bus di depan, sehingga cocok dengan kebutuhan dan anggaran pria itu. Pilihan A salah karena lokasinya dekat. Pilihan B salah karena sepupu itu baru akan pindah bulan depan. Pilihan C salah karena sewanya terjangkau."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'B', 37, $${"kind": "listening", "part": "B", "partTitle": "Part B — Long Conversations", "script": [{"s": "W", "t": "Did you see the listing for the apartment on Maple Street?"}, {"s": "M", "t": "Yeah, but it's way out of my budget. I'm looking for something under six hundred a month."}, {"s": "W", "t": "My cousin is moving out of her place next month. It's a two-bedroom, and the rent is pretty reasonable."}, {"s": "M", "t": "How far is it from campus?"}, {"s": "W", "t": "About a fifteen-minute walk. And there's a bus stop right outside."}, {"s": "M", "t": "That sounds perfect. When can I take a look at it?"}, {"s": "W", "t": "She's free this Saturday afternoon. I could go with you if you want."}, {"s": "M", "t": "That would be great. Thanks for thinking of me."}], "id": "LIS-B-02-Q4", "scriptId": "LIS-B-02", "stem": "What will the speakers probably do on Saturday?", "options": ["Sign a lease.", "Meet the cousin for lunch.", "Visit the apartment.", "Take the bus downtown."], "answer": 2, "explanation": "Wanita itu berkata sepupunya bisa ditemui hari Sabtu sore dan ia bisa menemani pria itu, jadi mereka kemungkinan akan melihat apartemennya. Pilihan A salah karena belum sampai tanda tangan kontrak. Pilihan B salah karena tujuannya melihat apartemen, bukan makan siang. Pilihan D tidak dibahas."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'C', 38, $${"kind": "listening", "part": "C", "partTitle": "Part C — Talks", "script": [{"s": "N", "t": "Today I want to talk about how plants survive in the desert, one of the harshest environments on Earth. With very little rainfall and extreme heat, you might expect nothing to grow there, but desert plants have developed remarkable adaptations. The cactus, for example, stores water in its thick, fleshy stem, and its leaves have evolved into spines. These spines reduce water loss and also protect the plant from animals looking for moisture. Other plants, like the creosote bush, have tiny, waxy leaves that limit evaporation. Some desert plants take a completely different approach: they avoid the dry season altogether. Annual wildflowers survive as seeds buried in the soil, sometimes for years, and they only sprout after rare heavy rains. Within days, the desert floor can be covered in color. So while the desert looks empty, it is actually full of clever survival strategies. Scientists study these adaptations not only out of curiosity, but also to develop crops that can survive in drier climates."}], "id": "LIS-C-01-Q1", "scriptId": "LIS-C-01", "stem": "What is the talk mainly about?", "options": ["How desert plants adapt to dry conditions.", "The history of desert exploration.", "Why deserts are expanding.", "How to grow cacti indoors."], "answer": 0, "explanation": "Ceramah membahas berbagai adaptasi tumbuhan gurun untuk bertahan di lingkungan kering dan panas. Pilihan B salah karena sejarah eksplorasi tidak dibahas. Pilihan C salah karena perluasan gurun tidak dibahas. Pilihan D salah karena cara menanam kaktus di dalam ruangan tidak dibahas."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'C', 39, $${"kind": "listening", "part": "C", "partTitle": "Part C — Talks", "script": [{"s": "N", "t": "Today I want to talk about how plants survive in the desert, one of the harshest environments on Earth. With very little rainfall and extreme heat, you might expect nothing to grow there, but desert plants have developed remarkable adaptations. The cactus, for example, stores water in its thick, fleshy stem, and its leaves have evolved into spines. These spines reduce water loss and also protect the plant from animals looking for moisture. Other plants, like the creosote bush, have tiny, waxy leaves that limit evaporation. Some desert plants take a completely different approach: they avoid the dry season altogether. Annual wildflowers survive as seeds buried in the soil, sometimes for years, and they only sprout after rare heavy rains. Within days, the desert floor can be covered in color. So while the desert looks empty, it is actually full of clever survival strategies. Scientists study these adaptations not only out of curiosity, but also to develop crops that can survive in drier climates."}], "id": "LIS-C-01-Q2", "scriptId": "LIS-C-01", "stem": "According to the speaker, what is one function of cactus spines?", "options": ["They absorb rainwater.", "They attract pollinators.", "They reduce water loss.", "They store nutrients."], "answer": 2, "explanation": "Pembicara berkata duri kaktus reduce water loss (mengurangi kehilangan air) dan melindungi dari hewan. Pilihan A salah karena duri tidak menyerap air hujan. Pilihan B salah karena tidak menarik penyerbuk. Pilihan D salah karena yang menyimpan air adalah batangnya, bukan durinya."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'C', 40, $${"kind": "listening", "part": "C", "partTitle": "Part C — Talks", "script": [{"s": "N", "t": "Today I want to talk about how plants survive in the desert, one of the harshest environments on Earth. With very little rainfall and extreme heat, you might expect nothing to grow there, but desert plants have developed remarkable adaptations. The cactus, for example, stores water in its thick, fleshy stem, and its leaves have evolved into spines. These spines reduce water loss and also protect the plant from animals looking for moisture. Other plants, like the creosote bush, have tiny, waxy leaves that limit evaporation. Some desert plants take a completely different approach: they avoid the dry season altogether. Annual wildflowers survive as seeds buried in the soil, sometimes for years, and they only sprout after rare heavy rains. Within days, the desert floor can be covered in color. So while the desert looks empty, it is actually full of clever survival strategies. Scientists study these adaptations not only out of curiosity, but also to develop crops that can survive in drier climates."}], "id": "LIS-C-01-Q3", "scriptId": "LIS-C-01", "stem": "How do annual wildflowers survive drought?", "options": ["By growing deep roots.", "By remaining as seeds until it rains.", "By storing water in their stems.", "By moving to shady areas."], "answer": 1, "explanation": "Pembicara berkata bunga liar tahunan survive as seeds buried in the soil dan baru bertunas setelah hujan lebat yang jarang terjadi. Pilihan A salah karena akar dalam tidak disebutkan. Pilihan C salah karena itu cara kaktus. Pilihan D salah karena tumbuhan tidak berpindah tempat."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'C', 41, $${"kind": "listening", "part": "C", "partTitle": "Part C — Talks", "script": [{"s": "N", "t": "Today I want to talk about how plants survive in the desert, one of the harshest environments on Earth. With very little rainfall and extreme heat, you might expect nothing to grow there, but desert plants have developed remarkable adaptations. The cactus, for example, stores water in its thick, fleshy stem, and its leaves have evolved into spines. These spines reduce water loss and also protect the plant from animals looking for moisture. Other plants, like the creosote bush, have tiny, waxy leaves that limit evaporation. Some desert plants take a completely different approach: they avoid the dry season altogether. Annual wildflowers survive as seeds buried in the soil, sometimes for years, and they only sprout after rare heavy rains. Within days, the desert floor can be covered in color. So while the desert looks empty, it is actually full of clever survival strategies. Scientists study these adaptations not only out of curiosity, but also to develop crops that can survive in drier climates."}], "id": "LIS-C-01-Q4", "scriptId": "LIS-C-01", "stem": "What does the speaker imply about deserts?", "options": ["They are completely lifeless.", "They receive no rainfall at all.", "They contain no useful plants.", "They are full of survival strategies."], "answer": 3, "explanation": "Kalimat penutup berkata gurun sebenarnya full of clever survival strategies, jadi gurun penuh strategi bertahan hidup yang cerdik. Pilihan A, B, dan C bertentangan dengan isi ceramah yang menunjukkan gurun penuh kehidupan."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'C', 42, $${"kind": "listening", "part": "C", "partTitle": "Part C — Talks", "script": [{"s": "N", "t": "In the 1440s, a German inventor named Johannes Gutenberg developed a printing press with movable metal type, and it changed the world. Before his invention, books had to be copied by hand, a slow process that made books extremely expensive. Only the wealthy, churches, and universities could afford them. Gutenberg's press could produce hundreds of pages per day, which brought the price of books down dramatically. Ideas could now spread faster than ever before. Scientists shared their discoveries, religious reformers spread their arguments, and news traveled across Europe in printed pamphlets. Some historians argue that the printing press did for knowledge what the internet would later do: it made information available to ordinary people. Of course, the press also spread misinformation, just as new media does today. Still, most scholars agree that without Gutenberg's invention, the rapid advances of the Renaissance and the Scientific Revolution might never have happened. His most famous product, the Gutenberg Bible, remains one of the most valuable books in the world."}], "id": "LIS-C-02-Q1", "scriptId": "LIS-C-02", "stem": "What is the talk mainly about?", "options": ["The life of Johannes Gutenberg.", "How books are printed today.", "The impact of the printing press.", "The history of German inventions."], "answer": 2, "explanation": "Ceramah membahas dampak mesin cetak Gutenberg terhadap penyebaran pengetahuan dan kemajuan zaman. Pilihan A salah karena riwayat hidup Gutenberg tidak dibahas detail. Pilihan B salah karena teknik cetak modern tidak dibahas. Pilihan D salah karena fokusnya bukan penemuan Jerman secara umum."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'C', 43, $${"kind": "listening", "part": "C", "partTitle": "Part C — Talks", "script": [{"s": "N", "t": "In the 1440s, a German inventor named Johannes Gutenberg developed a printing press with movable metal type, and it changed the world. Before his invention, books had to be copied by hand, a slow process that made books extremely expensive. Only the wealthy, churches, and universities could afford them. Gutenberg's press could produce hundreds of pages per day, which brought the price of books down dramatically. Ideas could now spread faster than ever before. Scientists shared their discoveries, religious reformers spread their arguments, and news traveled across Europe in printed pamphlets. Some historians argue that the printing press did for knowledge what the internet would later do: it made information available to ordinary people. Of course, the press also spread misinformation, just as new media does today. Still, most scholars agree that without Gutenberg's invention, the rapid advances of the Renaissance and the Scientific Revolution might never have happened. His most famous product, the Gutenberg Bible, remains one of the most valuable books in the world."}], "id": "LIS-C-02-Q2", "scriptId": "LIS-C-02", "stem": "Before the printing press, why were books expensive?", "options": ["They were copied by hand.", "Paper was extremely rare.", "Printers charged high fees.", "The church controlled all prices."], "answer": 0, "explanation": "Pembicara berkata books had to be copied by hand, a slow process that made books extremely expensive. Pilihan B salah karena kelangkaan kertas tidak disebutkan. Pilihan C salah karena belum ada percetakan. Pilihan D salah karena gereja hanya disebut sebagai pembeli, bukan pengendali harga."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'C', 44, $${"kind": "listening", "part": "C", "partTitle": "Part C — Talks", "script": [{"s": "N", "t": "In the 1440s, a German inventor named Johannes Gutenberg developed a printing press with movable metal type, and it changed the world. Before his invention, books had to be copied by hand, a slow process that made books extremely expensive. Only the wealthy, churches, and universities could afford them. Gutenberg's press could produce hundreds of pages per day, which brought the price of books down dramatically. Ideas could now spread faster than ever before. Scientists shared their discoveries, religious reformers spread their arguments, and news traveled across Europe in printed pamphlets. Some historians argue that the printing press did for knowledge what the internet would later do: it made information available to ordinary people. Of course, the press also spread misinformation, just as new media does today. Still, most scholars agree that without Gutenberg's invention, the rapid advances of the Renaissance and the Scientific Revolution might never have happened. His most famous product, the Gutenberg Bible, remains one of the most valuable books in the world."}], "id": "LIS-C-02-Q3", "scriptId": "LIS-C-02", "stem": "The speaker compares the printing press to the internet because both...", "options": ["were invented in Germany.", "replaced older technology completely.", "were only used by scholars.", "made information widely available."], "answer": 3, "explanation": "Pembicara berkata mesin cetak did for knowledge what the internet would later do: it made information available to ordinary people. Pilihan A salah karena internet tidak ditemukan di Jerman. Pilihan B salah karena tidak dibilang menggantikan total. Pilihan C salah karena justru untuk orang biasa."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'C', 45, $${"kind": "listening", "part": "C", "partTitle": "Part C — Talks", "script": [{"s": "N", "t": "In the 1440s, a German inventor named Johannes Gutenberg developed a printing press with movable metal type, and it changed the world. Before his invention, books had to be copied by hand, a slow process that made books extremely expensive. Only the wealthy, churches, and universities could afford them. Gutenberg's press could produce hundreds of pages per day, which brought the price of books down dramatically. Ideas could now spread faster than ever before. Scientists shared their discoveries, religious reformers spread their arguments, and news traveled across Europe in printed pamphlets. Some historians argue that the printing press did for knowledge what the internet would later do: it made information available to ordinary people. Of course, the press also spread misinformation, just as new media does today. Still, most scholars agree that without Gutenberg's invention, the rapid advances of the Renaissance and the Scientific Revolution might never have happened. His most famous product, the Gutenberg Bible, remains one of the most valuable books in the world."}], "id": "LIS-C-02-Q4", "scriptId": "LIS-C-02", "stem": "According to the speaker, what might not have happened without the printing press?", "options": ["The invention of paper.", "The advances of the Renaissance and Scientific Revolution.", "The spread of misinformation.", "The writing of the Bible."], "answer": 1, "explanation": "Pembicara berkata tanpa penemuan Gutenberg, the rapid advances of the Renaissance and the Scientific Revolution might never have happened. Pilihan A salah karena kertas sudah ada sebelumnya. Pilihan C salah karena misinformasi justru ikut tersebar. Pilihan D salah karena Alkitab sudah ditulis jauh sebelumnya."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'C', 46, $${"kind": "listening", "part": "C", "partTitle": "Part C — Talks", "script": [{"s": "N", "t": "Impressionism was a radical art movement that began in France in the 1870s. Before it appeared, most respected painters worked indoors in studios, creating detailed, carefully finished scenes from history or mythology. The Impressionists broke these rules. Artists like Claude Monet and Pierre-Auguste Renoir took their easels outside and painted quickly, trying to capture the changing light of a single moment. Instead of mixing colors smoothly on a palette, they placed small dabs of pure color side by side on the canvas, letting the viewer's eye blend them together. At first, critics laughed at the unfinished look. In fact, the name Impressionism came from a mocking review of Monet's painting Impression, Sunrise. But the public eventually embraced the fresh, lively style. Today, Impressionist paintings are among the most beloved in the world, and the movement opened the door to modern art by proving that a painting did not have to look like a photograph to be powerful."}], "id": "LIS-C-03-Q1", "scriptId": "LIS-C-03", "stem": "What is the talk mainly about?", "options": ["A famous French museum.", "The life of Claude Monet.", "The Impressionist art movement.", "Modern photography."], "answer": 2, "explanation": "Ceramah membahas gerakan seni Impresionisme: awal mulanya, tekniknya, dan pengaruhnya. Pilihan A salah karena museum tidak dibahas. Pilihan B salah karena riwayat hidup Monet tidak dibahas. Pilihan D salah karena fotografi hanya disebut sebagai pembanding."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'C', 47, $${"kind": "listening", "part": "C", "partTitle": "Part C — Talks", "script": [{"s": "N", "t": "Impressionism was a radical art movement that began in France in the 1870s. Before it appeared, most respected painters worked indoors in studios, creating detailed, carefully finished scenes from history or mythology. The Impressionists broke these rules. Artists like Claude Monet and Pierre-Auguste Renoir took their easels outside and painted quickly, trying to capture the changing light of a single moment. Instead of mixing colors smoothly on a palette, they placed small dabs of pure color side by side on the canvas, letting the viewer's eye blend them together. At first, critics laughed at the unfinished look. In fact, the name Impressionism came from a mocking review of Monet's painting Impression, Sunrise. But the public eventually embraced the fresh, lively style. Today, Impressionist paintings are among the most beloved in the world, and the movement opened the door to modern art by proving that a painting did not have to look like a photograph to be powerful."}], "id": "LIS-C-03-Q2", "scriptId": "LIS-C-03", "stem": "How did the Impressionists paint differently?", "options": ["They painted only at night.", "They used only black and white.", "They copied photographs.", "They painted outdoors to capture changing light."], "answer": 3, "explanation": "Pembicara berkata mereka took their easels outside and painted quickly, trying to capture the changing light of a single moment. Pilihan A salah karena tidak disebut melukis malam hari. Pilihan B salah karena mereka justru memakai warna murni. Pilihan C salah karena mereka menolak lukisan yang mirip foto."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'C', 48, $${"kind": "listening", "part": "C", "partTitle": "Part C — Talks", "script": [{"s": "N", "t": "Impressionism was a radical art movement that began in France in the 1870s. Before it appeared, most respected painters worked indoors in studios, creating detailed, carefully finished scenes from history or mythology. The Impressionists broke these rules. Artists like Claude Monet and Pierre-Auguste Renoir took their easels outside and painted quickly, trying to capture the changing light of a single moment. Instead of mixing colors smoothly on a palette, they placed small dabs of pure color side by side on the canvas, letting the viewer's eye blend them together. At first, critics laughed at the unfinished look. In fact, the name Impressionism came from a mocking review of Monet's painting Impression, Sunrise. But the public eventually embraced the fresh, lively style. Today, Impressionist paintings are among the most beloved in the world, and the movement opened the door to modern art by proving that a painting did not have to look like a photograph to be powerful."}], "id": "LIS-C-03-Q3", "scriptId": "LIS-C-03", "stem": "Where did the name Impressionism come from?", "options": ["A mocking review of a Monet painting.", "A French art school.", "A book about color theory.", "Monet's personal diary."], "answer": 0, "explanation": "Pembicara berkata nama itu came from a mocking review of Monet's painting Impression, Sunrise, yaitu dari ulasan yang mengejek. Pilihan B, C, dan D tidak disebutkan."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'C', 49, $${"kind": "listening", "part": "C", "partTitle": "Part C — Talks", "script": [{"s": "N", "t": "Impressionism was a radical art movement that began in France in the 1870s. Before it appeared, most respected painters worked indoors in studios, creating detailed, carefully finished scenes from history or mythology. The Impressionists broke these rules. Artists like Claude Monet and Pierre-Auguste Renoir took their easels outside and painted quickly, trying to capture the changing light of a single moment. Instead of mixing colors smoothly on a palette, they placed small dabs of pure color side by side on the canvas, letting the viewer's eye blend them together. At first, critics laughed at the unfinished look. In fact, the name Impressionism came from a mocking review of Monet's painting Impression, Sunrise. But the public eventually embraced the fresh, lively style. Today, Impressionist paintings are among the most beloved in the world, and the movement opened the door to modern art by proving that a painting did not have to look like a photograph to be powerful."}], "id": "LIS-C-03-Q4", "scriptId": "LIS-C-03", "stem": "What does the speaker imply about Impressionism's influence?", "options": ["It ended all interest in realistic painting.", "It helped pave the way for modern art.", "It was forgotten after the 1870s.", "It discouraged outdoor painting."], "answer": 1, "explanation": "Pembicara berkata gerakan ini opened the door to modern art, artinya membuka jalan bagi seni modern. Pilihan A salah karena tidak dibilang mengakhiri lukisan realis. Pilihan C salah karena lukisannya justru sangat dicintai hingga kini. Pilihan D salah karena mereka mempopulerkan melukis di luar ruangan."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Structure', 50, $${"id": "STR-01", "kind": "mcq", "part": "Structure", "stem": "The committee members _____ strong disagreement over the budget proposal for weeks.", "options": ["has expressed", "have expressed", "expresses", "was expressing"], "answer": 1, "explanation": "Subjeknya 'members' yang berbentuk jamak, jadi kata kerjanya harus ikut jamak: 'have expressed'. Pilihan 'has expressed', 'expresses', dan 'was expressing' semuanya bentuk tunggal sehingga tidak cocok. Present perfect juga pas karena ada keterangan durasi 'for weeks'.", "topic": "subject-verb agreement"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Structure', 51, $${"id": "STR-02", "kind": "mcq", "part": "Structure", "stem": "By the time the rescue team arrived, the hikers _____ for nearly twelve hours.", "options": ["had been waiting", "have waited", "are waiting", "will wait"], "answer": 0, "explanation": "Ada dua kejadian lampau di sini: tim penyelamat tiba, dan para pendaki sudah menunggu sebelumnya. Untuk kejadian yang terjadi lebih dulu dan berlangsung dalam suatu durasi ('for nearly twelve hours'), dipakai past perfect continuous: 'had been waiting'.", "topic": "verb forms/tenses"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Structure', 52, $${"id": "STR-03", "kind": "mcq", "part": "Structure", "stem": "The new training program teaches employees how to communicate clearly, _____ problems quickly, and adapt to change.", "options": ["solving", "solved", "solve", "to solving"], "answer": 2, "explanation": "Setelah 'how to' ada tiga unsur yang harus sejajar: 'communicate', ..., 'adapt'. Semuanya bare infinitive, jadi bagian yang rumpang harus 'solve', bukan 'solving', 'solved', atau 'to solving'.", "topic": "parallel structure"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Structure', 53, $${"id": "STR-04", "kind": "mcq", "part": "Structure", "stem": "The Pacific Ocean is _____ than any other ocean in the world.", "options": ["more deep", "deepest", "the deeper", "deeper"], "answer": 3, "explanation": "'Deep' hanya satu suku kata, jadi bentuk comparative-nya 'deeper', bukan 'more deep'. Kata 'than' juga menandakan ini comparative, bukan superlative seperti 'deepest'.", "topic": "comparatives"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Structure', 54, $${"id": "STR-05", "kind": "mcq", "part": "Structure", "stem": "The manager has not decided _____ to approve the budget proposal this quarter.", "options": ["whether", "if not", "that", "which"], "answer": 0, "explanation": "'Whether' dipakai untuk klausa nomina yang menyatakan pilihan atau ketidakpastian, dan bisa diikuti to-infinitive: 'decided whether to approve'. 'That' tidak bisa diikuti to-infinitive, 'if not' bukan frasa baku, dan 'which' dipakai untuk memilih di antara benda, tidak cocok di sini.", "topic": "noun clauses"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Structure', 55, $${"id": "STR-06", "kind": "mcq", "part": "Structure", "stem": "The botanical garden, _____ was established in 1923, attracts thousands of visitors every spring.", "options": ["that", "which", "what", "whose"], "answer": 1, "explanation": "Klausa ini nonrestrictive (diapit koma), jadi tidak boleh memakai 'that'. Untuk kata benda, relative pronoun yang tepat adalah 'which'. 'What' dan 'whose' tidak cocok di kalimat ini.", "topic": "adjective clauses"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Structure', 56, $${"id": "STR-07", "kind": "mcq", "part": "Structure", "stem": "_____ carefully before signing, the contract contained several unfair clauses that the tenant overlooked.", "options": ["Not read", "Not to read", "Not having been read", "Not being read"], "answer": 2, "explanation": "Subjek kalimatnya 'the contract', jadi klausa yang direduksi harus berbentuk pasif: 'not having been read'. Bentuk perfect dipakai karena kejadiannya terjadi sebelum klausa utama. 'Not being read' bermakna sedang dibaca, tidak cocok dengan konteks lampau di sini.", "topic": "adverb clauses/reduced"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Structure', 57, $${"id": "STR-08", "kind": "mcq", "part": "Structure", "stem": "Not only _____ the exhibition, but she also purchased two paintings from the local artist.", "options": ["she visited", "did she visits", "she did visit", "did she visit"], "answer": 3, "explanation": "Kalimat diawali ekspresi negatif 'not only', sehingga urutannya dibalik: auxiliary + subjek, yaitu 'did she visit'. Setelah 'did', kata kerja harus bentuk dasar, jadi 'did she visits' salah.", "topic": "inversion"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Structure', 58, $${"id": "STR-09", "kind": "mcq", "part": "Structure", "stem": "The results of the experiment, _____ over a period of six months, were finally published in a scientific journal.", "options": ["conducted", "conducting", "to conduct", "being conduct"], "answer": 0, "explanation": "Ini reduced relative clause dari 'which were conducted'. Karena subjeknya 'the results' (benda yang dikenai tindakan), dipakai past participle 'conducted'. 'Conducting' bermakna aktif sehingga tidak cocok.", "topic": "participles"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Structure', 59, $${"id": "STR-10", "kind": "mcq", "part": "Structure", "stem": "The receptionist could not tell us _____.", "options": ["when does the meeting start", "when the meeting starts", "when the meeting does start", "when starts the meeting"], "answer": 1, "explanation": "Ini indirect question (pertanyaan tidak langsung), jadi tidak boleh ada inversi seperti pada pertanyaan langsung. Urutannya tetap subjek + verb: 'when the meeting starts'.", "topic": "word order"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Structure', 60, $${"id": "STR-11", "kind": "mcq", "part": "Structure", "stem": "_____ unique opportunity to study abroad is rarely offered to first-year students.", "options": ["A", "An", "The", "Some"], "answer": 0, "explanation": "'Unique' diawali bunyi konsonan /j/, jadi artikelnya 'a', bukan 'an'. 'The' butuh konteks yang sudah spesifik, dan 'some' tidak dipakai dengan kata benda tunggal countable.", "topic": "articles"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Structure', 61, $${"id": "STR-12", "kind": "mcq", "part": "Structure", "stem": "The supervisor is responsible _____ training the new interns every semester.", "options": ["with", "of", "to", "for"], "answer": 3, "explanation": "Pasangan yang baku adalah 'responsible for'. 'Responsible with', 'responsible of', dan 'responsible to' bukan kolokasi yang benar.", "topic": "prepositions"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Structure', 62, $${"id": "STR-13", "kind": "mcq", "part": "Structure", "stem": "_____ the heavy rain, the outdoor concert was held as scheduled.", "options": ["Although", "Despite", "Because", "Whereas"], "answer": 1, "explanation": "'Despite' diikuti frasa nomina ('the heavy rain'). 'Although', 'because', dan 'whereas' harus diikuti klausa lengkap (subjek + verb), jadi tidak bisa dipakai di sini.", "topic": "conjunctions"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Structure', 63, $${"id": "STR-14", "kind": "mcq", "part": "Structure", "stem": "The news _____ better than expected this morning.", "options": ["were", "are", "was", "have been"], "answer": 2, "explanation": "'News' itu kata benda singular (tidak punya bentuk jamak), jadi verb-nya 'was'. Jangan terkecoh akhiran -s yang menyerupai bentuk jamak.", "topic": "singular/plural"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Structure', 64, $${"id": "STR-15", "kind": "mcq", "part": "Structure", "stem": "The scientist's _____ explanation of the theory made it accessible to the general public.", "options": ["clarity", "clearly", "clear", "clearing"], "answer": 2, "explanation": "Yang dibutuhkan adalah adjective untuk menerangkan kata benda 'explanation', yaitu 'clear'. 'Clarity' itu noun, 'clearly' adverb, dan 'clearing' tidak cocok maknanya.", "topic": "word forms"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 65, $${"id": "WE-01", "kind": "we", "part": "Written Expression", "tokens": ["The new manager ", "is known for", " his dedication, ", "his punctuality", ", and ", "working overtime every weekend", "."], "marks": [1, 3, 4, 5], "answer": "D", "explanation": "Ketiga unsur setelah 'for' harus sejajar. 'His dedication' dan 'his punctuality' berbentuk frasa nomina, sedangkan 'working overtime every weekend' berbentuk frasa verba. Perbaikannya misalnya menjadi 'his willingness to work overtime'. Bagian A benar (bentuk pasif 'is known for'), B benar (frasa nomina), dan C benar (konjungsi penyejajar).", "topic": "parallel structure"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 66, $${"id": "WE-02", "kind": "we", "part": "Written Expression", "tokens": ["The stack of newspapers on the desk ", "need", " to be recycled ", "before Friday", "."], "marks": [0, 1, 2, 3], "answer": "B", "explanation": "Subjek kalimat ini 'the stack' (tumpukan) yang tunggal; frasa 'of newspapers on the desk' hanya keterangan dan tidak menentukan verb. Jadi harusnya 'needs', bukan 'need'.", "topic": "subject-verb agreement"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 67, $${"id": "WE-03", "kind": "we", "part": "Written Expression", "tokens": ["She ", "speaks English", " very ", "fluent", " after living abroad for two years", "."], "marks": [0, 1, 3, 4], "answer": "C", "explanation": "Kata yang menerangkan verb 'speaks' harus adverb, yaitu 'fluently'. 'Fluent' adalah adjective yang menerangkan kata benda, jadi salah dipakai di sini.", "topic": "word form (adjective vs adverb)"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 68, $${"id": "WE-04", "kind": "we", "part": "Written Expression", "tokens": ["A", " honest answer is always better than ", "a", " convenient lie", "."], "marks": [0, 1, 2, 3], "answer": "A", "explanation": "'Honest' diawali bunyi vokal (huruf h-nya tidak dibaca), jadi artikelnya 'an', bukan 'a'. Bagian C sudah benar karena 'convenient' diawali bunyi konsonan.", "topic": "articles"}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('structure', 'Written Expression', 69, $${"id": "WE-05", "kind": "we", "part": "Written Expression", "tokens": ["The committee will meet ", "on", " Monday to discuss", " about", " the new policy", "."], "marks": [0, 1, 2, 3], "answer": "D", "explanation": "'Discuss' sudah kata kerja transitif yang langsung diikuti objek, jadi kata 'about' di sini berlebihan dan harus dihapus. 'On Monday' di bagian B sudah benar.", "topic": "preposition (redundant)"}$$::jsonb);
